create function touch_updated() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create table products(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,kind text not null check(kind in ('wine','cider','spirit','beer')),litres_per_unit numeric(12,4) not null check(litres_per_unit>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table locations(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,country text not null check(country in ('NZ','AU')),licence_ref text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table vessels(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table contacts(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,email text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table batches(id uuid primary key default gen_random_uuid(),code text not null unique,product_id uuid not null references products,vessel_id uuid references vessels,produced_on date not null,abv numeric(6,3) check(abv>0 and abv<=100),source_ref text,status text not null default 'hold' check(status in ('hold','released')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table orders(id uuid primary key default gen_random_uuid(),code text not null unique,contact_id uuid not null references contacts,location_id uuid not null references locations,due_on date not null,status text not null default 'open' check(status in ('open','dispatched')),carrier text,consignment text,delivered_on date,duty_ref text,tax_basis text not null default 'review' check(tax_basis in ('review','NZ-excise','AU-excise','AU-WET')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table order_lines(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders,batch_id uuid not null references batches,units numeric(14,3) not null check(units>0),unit_price numeric(14,2) not null check(unit_price>=0),currency text not null check(currency in ('NZD','AUD')),unique(order_id,batch_id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table movements(id uuid primary key default gen_random_uuid(),ref text not null unique,batch_id uuid not null references batches,location_id uuid not null references locations,order_id uuid references orders,kind text not null check(kind in ('receipt','dispatch','loss','adjustment')),units numeric(14,3) not null check(units<>0),occurred_on date not null default current_date,evidence text not null check(length(trim(evidence))>0),check((kind='receipt' and units>0) or (kind in ('dispatch','loss') and units<0) or kind='adjustment'),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table analyses(id uuid primary key default gen_random_uuid(),batch_id uuid not null references batches,tested_on date not null,abv numeric(6,3) not null check(abv>0 and abv<=100),evidence text not null check(length(trim(evidence))>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table notes(id uuid primary key default gen_random_uuid(),batch_id uuid not null references batches,body text not null check(length(trim(body))>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['products','locations','vessels','contacts','batches','orders','order_lines','movements','analyses','notes'] loop execute format('create trigger updated before update on %I for each row execute function touch_updated()',t); end loop; end $$;
create function immutable_movement() returns trigger language plpgsql as $$ begin raise exception 'Movement history is append-only. Add a correcting adjustment with evidence.'; end $$;
create trigger preserve_movement before update or delete on movements for each row execute function immutable_movement();
create view v_stock as select b.id batch_id,l.id location_id,b.code batch,p.name product,l.code location,b.status,b.abv,p.litres_per_unit,coalesce(sum(m.units),0) units,round(coalesce(sum(m.units),0)*p.litres_per_unit,3) litres,round(coalesce(sum(m.units),0)*p.litres_per_unit*b.abv/100,3) litres_alcohol,current_date-b.produced_on age_days from batches b join products p on p.id=b.product_id cross join locations l left join movements m on m.batch_id=b.id and m.location_id=l.id group by b.id,p.id,l.id;
create view v_dispatch as select o.id,o.code,o.due_on,c.name customer,l.code location,b.code batch,b.status batch_status,ol.units required,coalesce(s.units,0) available,greatest(ol.units-coalesce(s.units,0),0) short_units,o.tax_basis from orders o join contacts c on c.id=o.contact_id join locations l on l.id=o.location_id join order_lines ol on ol.order_id=o.id join batches b on b.id=ol.batch_id left join v_stock s on s.batch_id=b.id and s.location_id=l.id where o.status='open';
create view v_excise_records as select m.id,m.occurred_on,m.ref,b.code batch,p.kind,l.country,l.code location,m.kind movement,m.units,round(abs(m.units)*p.litres_per_unit,3) litres,b.abv,round(abs(m.units)*p.litres_per_unit*b.abv/100,3) litres_alcohol,o.code sales_order,o.tax_basis,o.duty_ref,m.evidence from movements m join batches b on b.id=m.batch_id join products p on p.id=b.product_id join locations l on l.id=m.location_id left join orders o on o.id=m.order_id;
create view v_compliance as
select 'BATCH-EVIDENCE' rule,b.code record,'ABV or production source missing' issue from batches b where b.abv is null or nullif(trim(b.source_ref),'') is null
union all select 'LICENCE-REFERENCE',code,'Location licence reference missing' from locations where nullif(trim(licence_ref),'') is null
union all select 'DISPATCH-EVIDENCE',code,'Carrier, consignment or duty reference missing' from orders where status='dispatched' and (nullif(trim(carrier),'') is null or nullif(trim(consignment),'') is null or nullif(trim(duty_ref),'') is null)
union all select 'TAX-CLASSIFICATION',code,'Tax treatment needs operator review' from orders where tax_basis='review'
union all select 'STOCK-NEGATIVE',batch||' / '||location,'Movement balance is below zero' from v_stock where units<0
union all select 'DELIVERY-CONFIRMATION',code,'Dispatched order has no recorded delivery confirmation' from orders where status='dispatched' and delivered_on is null;
create view v_attention as select 'order' kind,code record,'Dispatch overdue' issue from orders where status='open' and due_on<current_date
union all select 'batch',b.code,'No analysis in 30 days (house rule)' from batches b where not exists(select 1 from analyses a where a.batch_id=b.id and a.tested_on>=current_date-30)
union all select 'hold',code,'Batch held from dispatch' from batches where status='hold'
union all select 'compliance',record,issue from v_compliance;
